// Auth check block 1/4 - read the bearer token. Never log it.
const headers = $('Webhook').first().json.headers || {};
const raw = headers.authorization || headers.Authorization || '';
const match = /^Bearer\s+(\S+)$/i.exec(String(raw).trim());
return [{ json: { token: match ? match[1] : '' } }];

// Auth check block 4/4 - decide. Output: { ok, status, error?, user? }
const cfg = $('Config').first().json;
const token = $('Auth: read token').first().json.token;
const userRes = $('Auth: verify token').first().json;
const profileRes = $('Auth: load profile').first().json;

const deny = (status, error) => [{ json: { ok: false, status, error } }];

if (!token) return deny(401, 'Missing login token.');
if (userRes.statusCode !== 200 || !userRes.body || !userRes.body.id) {
  return deny(401, 'Login token is not valid or has expired.');
}
if (profileRes.statusCode !== 200) return deny(500, 'Could not load the login profile.');

const rows = Array.isArray(profileRes.body) ? profileRes.body : [];
const profile = rows[0];
if (!profile || profile.user_id !== userRes.body.id) return deny(403, 'This login has no access.');
if (profile.disabled) return deny(403, 'This login has been turned off.');
if (!cfg.ALLOWED_ROLES.includes(profile.role)) {
  return deny(403, 'Your role does not allow this action.');
}

return [{
